# Checkout Component Test Suite

*adjusts spectacles and settles into chair*

Buffalo bagels! Let's get this sorted out. I've been writing test suites since before React was a twinkle in Facebook's eye.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Test fixtures
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-123' }),
};

const validShipping = {
  street: '123 Main St',
  city: 'Springfield',
  state: 'CA',
  zip: '90210',
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe',
};

const renderCheckout = () => render(
  <CartContext.Provider value={mockCart}>
    <PaymentContext.Provider value={mockPayment}>
      <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
    </PaymentContext.Provider>
  </CartContext.Provider>
);

describe('Checkout', () => {
  beforeEach(() => vi.clearAllMocks());

  // Happy Path
  describe('complete checkout flow', () => {
    it('navigates shipping → payment → review → confirmation', async () => {
      const user = userEvent.setup();
      renderCheckout();

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ORD-123/)).toBeInTheDocument();
      });
    });
  });

  // Validation
  describe('form validation', () => {
    it('displays error for invalid ZIP code', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });
  });

  // Edge Cases
  describe('edge cases', () => {
    it('shows empty cart message when no items', () => {
      render(<Checkout />, { wrapper: ({ children }) => (
        <CartContext.Provider value={{ items: [], total: 0, clearCart: vi.fn() }}>
          {children}
        </CartContext.Provider>
      )});

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // Accessibility
  it('has no accessibility violations', async () => {
    const { container } = renderCheckout();
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

The coordination will proceed in an orderly fashion. Tests focus on user behavior, not implementation details.
